"""Offline contract tests; generated bytes are NOT physical FPGA evidence."""
import contextlib
import io
import struct
import subprocess
import sys
import tempfile
import types
import unittest
from pathlib import Path
from unittest.mock import patch

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import serial_dump as dump


EXPECTED_REGS = [0xFFFFFFFF, 0xFFFFFFFF, 0xFF, 0x80,
                 0xFFFF80FF, 0x80FF, 0x008080FF, 0x5C]
EXPECTED_MEM = [0x008080FF, 0x5C, 0x70, 7, 0x008080FF] + [0] * 27


def fixture():
    return struct.pack('<41I', 12345, *EXPECTED_REGS, *EXPECTED_MEM)


def cli(*args):
    return subprocess.run([sys.executable, str(HERE / 'serial_dump.py'), *map(str, args)],
                          text=True, capture_output=True)


class OfflineDumpTests(unittest.TestCase):
    def test_receive_chunks_resets_buffer_and_closes_port(self):
        class FakePort:
            closed = False
            reset = False

            def __init__(self):
                self.remaining = fixture()

            def reset_input_buffer(self):
                self.reset = True

            def read(self, size):
                result = self.remaining[:min(7, size)]
                self.remaining = self.remaining[len(result):]
                return result

            def close(self):
                self.closed = True

        fake = FakePort()
        with patch.dict(sys.modules, {'serial': types.SimpleNamespace(Serial=lambda *a, **kw: fake)}):
            with contextlib.redirect_stdout(io.StringIO()):
                self.assertEqual(dump.receive_dump('fake', 9600, 1), fixture())
        self.assertTrue(fake.reset)
        self.assertTrue(fake.closed)

    def test_exact_164_bytes_and_expected_fields(self):
        self.assertEqual(len(fixture()), 164)
        self.assertEqual([], dump.compare_etapa03(dump.parse_dump(fixture())))

    def test_every_register_and_memory_word_compared(self):
        for offset in range(4, 164, 4):
            label = f'x{offset // 4}' if offset < 36 else f'0x{offset - 36:03X}'
            raw = bytearray(fixture())
            raw[offset] ^= 1
            mismatches = dump.compare_etapa03(dump.parse_dump(bytes(raw)))
            self.assertEqual(len(mismatches), 1)
            self.assertIn(label, mismatches[0])
        raw = bytearray(fixture())
        raw[0] ^= 1
        self.assertEqual([], dump.compare_etapa03(dump.parse_dump(bytes(raw))))

    def test_rejects_short_or_extra_data(self):
        for raw in (fixture()[:-1], fixture() + b'\x00'):
            with self.assertRaisesRegex(ValueError, '164'):
                dump.parse_dump(raw)

    def test_report_cannot_overwrite_input_capture(self):
        with tempfile.TemporaryDirectory() as d:
            capture = Path(d) / 'capture.bin'
            capture.write_bytes(fixture())
            result = cli('--input', capture, '--out', capture, '--check-etapa03')
            self.assertNotEqual(result.returncode, 0)
            self.assertEqual(capture.read_bytes(), fixture())

    def test_report_cannot_target_raw_capture_path(self):
        with tempfile.TemporaryDirectory() as d:
            capture = Path(d) / 'capture.bin'
            result = cli('COM_TEST', '--raw-out', capture, '--out', capture)
            self.assertNotEqual(result.returncode, 0)
            self.assertIn('mesmo arquivo', result.stderr)
            self.assertFalse(capture.exists())

    def test_offline_cli_pass_fail_and_raw_preservation(self):
        with tempfile.TemporaryDirectory() as d:
            directory = Path(d)
            inp = directory / 'fixture.bin'
            inp.write_bytes(fixture())
            report = directory / 'report.txt'
            ok = cli('--input', inp, '--check-etapa03', '--out', report)
            self.assertEqual(ok.returncode, 0, ok.stderr)
            self.assertIn('PASS', ok.stdout)
            self.assertIn('PASS etapa 3', report.read_text())
            bad = bytearray(fixture())
            bad[40] ^= 1
            inp.write_bytes(bad)
            fail = cli('--input', inp, '--check-etapa03', '--out', report)
            self.assertNotEqual(fail.returncode, 0)
            self.assertIn('0x004', fail.stdout)
            self.assertIn('FAIL etapa 3', report.read_text())
            inp.write_bytes(fixture()[:-1])
            short = cli('--input', inp, '--check-etapa03', '--out', report)
            self.assertNotEqual(short.returncode, 0)
            self.assertIn('164', short.stderr)


if __name__ == '__main__':
    unittest.main()
